db:select.db:input-parameters:
#[{
                propertyType: vars.queryFilters.propertyType,
                status: vars.queryFilters.status,
                lastModifiedFrom: vars.queryFilters.lastModifiedFrom
            }]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    data: vars.properties map (property) -> {
        propertyId: property.propertyId,
        propertyType: property.propertyType,
        address: {
            street: property.street,
            city: property.city,
            state: property.state,
            postalCode: property.postalCode,
            country: property.country
        },
        valuation: {
            currentValue: property.currentValue,
            currency: property.currency,
            valuationDate: property.valuationDate,
            valuationMethod: property.valuationMethod
        },
        ownership: {
            ownerId: property.ownerId,
            ownerName: property.ownerName,
            ownershipType: property.ownershipType,
            acquisitionDate: property.acquisitionDate
        },
        status: property.status,
        createdDate: property.createdDate,
        lastModifiedDate: property.lastModifiedDate,
        source: property.source
    },
    metadata: {
        totalCount: vars.totalCount,
        limit: attributes.queryParams.limit default 100,
        offset: attributes.queryParams.offset default 0
    }
}
